pragma solidity >=0.8.13;
contract StringsProbe {
    string public stored;
    bytes public blob;
    string public lastConcat;
    event Stored(string s, bytes b);
    function setString(string memory s) public {
        stored = s;
        emit Stored(s, blob);
    }
    function setBytes(bytes memory b) public {
        blob = b;
    }
    function concatAndStore(string memory a, string memory b) public {
        lastConcat = string.concat(a, b);
        emit Stored(lastConcat, blob);
    }
    function echoNames(string[] memory names) public returns (uint256) {
        return names.length;
    }
    function getNames() public view returns (string[] memory) {
        string[] memory r = new string[](3);
        r[0] = stored;
        r[1] = "";
        r[2] = "abcdefghijklmnopqrstuvwxyzabcdefg";
        return r;
    }
}
